#ifndef STM_PROJECTOR_H
#define STM_PROJECTOR_H

#include <chrono>
#include <cstdint>
#include <filesystem>
#include <memory>
#include <string>

#include "event.h"
#include "metric_sample_projector.h"
#include "journal_reader.h"
#include "timeline.h"
#include "topology_projector.h"
#include "topology_state_projector.h"
#include "stream_state_projector.h"
#include "writer.h"

class stm_projector {
public:
	struct config {
		std::filesystem::path event_journal_dir;
		std::filesystem::path metrics_journal_dir;
		std::filesystem::path output_dir;
		std::filesystem::path state_file;
		std::uint64_t timeline_rotate_size_bytes{2ULL * 1024ULL * 1024ULL};
		std::size_t timeline_rotate_files{3};
		std::chrono::milliseconds poll_interval{1000};
		// Coalesce full topology materialization. Lifecycle events remain
		// individually recorded in the event and topology-event journals.
		std::chrono::milliseconds topology_publish_interval{1000};
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
		std::uint32_t topology_checkpoint_interval_sec{60U};
		std::uint32_t inactive_retention_sec{300U};
	};

	explicit stm_projector(config cfg);
	int run_once();
	int run_follow();

private:
	config m_cfg;
	journal_reader m_events;
	journal_reader m_metrics;
	journal_reader::cursor m_event_cursor;
	journal_reader::cursor m_metrics_cursor;
	std::unique_ptr<writer> m_timeline_writer;
	std::unique_ptr<timeline_sink> m_timeline_sink;
	std::unique_ptr<timeline_projector> m_timeline_projector;
	std::unique_ptr<time_rotating_writer> m_timeline_availability_writer;
	std::unique_ptr<metric_sample_projector> m_metrics_projector;
	std::unique_ptr<stream_state_projector> m_stream_state;
	std::unique_ptr<topology_projector> m_topology_projector;
	std::unique_ptr<topology_state_projector> m_topology_state;
	std::unique_ptr<writer> m_topology_writer;
	std::unique_ptr<time_rotating_writer> m_topology_events_writer;
	json::array_t m_current_metrics;
	json::array_t m_current_interfaces;
	json m_active_alerts = json::object();
	std::uint64_t m_last_player_cycle{0};
	bool m_has_player_cycle{false};
	std::string m_last_event_record_id;
	std::string m_last_metrics_record_id;
	bool m_topology_dirty{false};
	double m_pending_topology_time{0.0};
	json m_pending_topology_source = json::object();
	std::chrono::steady_clock::time_point m_last_topology_publish{};

	void load_state();
	bool save_state() const;
	int project_event(const json &record);
	int project_metrics(const json &record);
	void observe_player_cycle(const json &record);
	void mark_topology_dirty(double time, const json &source);
	bool flush_topology_if_due();
	void write_topology(double time, const json &source);
	void write_topology_event(const json &event);
};

#endif /* STM_PROJECTOR_H */
#ifndef METRIC_SAMPLE_PROJECTOR_H
#define METRIC_SAMPLE_PROJECTOR_H

#include <cstdint>
#include <filesystem>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <set>

#include "json.h"
#include "metrics_common.h"
#include "writer.h"

/** Projects metrics-journal snapshots into target-addressable metric samples. */
class metric_sample_projector {
public:
	struct config {
		std::filesystem::path root_dir{"metrics"};
		std::filesystem::path samples_1s_dir{"samples/1s"};
		std::filesystem::path samples_1m_dir{"samples/1m"};
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
	};

	explicit metric_sample_projector(config cfg);
	~metric_sample_projector();

	void append_snapshot(double now,
	                     const json::array_t &metrics,
	                     const json::array_t &interfaces,
	                     const json &source_record);

private:
	struct subject_accumulator {
		json target;
		json template_metrics;
		std::map<std::string, metrics::value_stats> stats_by_path;
		std::map<std::string, double> last_by_path;
		std::set<std::string> interval_paths;
		std::string capture_id;
		std::string source_record_id;
	};

	struct minute_bucket {
		double bucket_start{0.0};
		double bucket_end{0.0};
		std::map<std::string, subject_accumulator> subjects;
	};

	config m_cfg;
	std::unique_ptr<time_rotating_writer> m_samples_1s_writer;
	std::unique_ptr<time_rotating_writer> m_samples_1m_writer;
	std::optional<minute_bucket> m_bucket;
	std::uint64_t m_rollup_sequence{0};

	static double minute_floor(double now);
	static std::string target_key(const json &entry, bool is_interface);
	static json make_target(const json &entry, bool is_interface);
	static bool is_stat_object(const json &value);
	static json make_template(const json &value);
	static double first_stat_value(const json &record);
	static void collect_values(const std::string &prefix, const json &value, std::map<std::string, double> &out, std::set<std::string> &interval_paths);
	static void set_path(json &out, const std::string &path, json value);

	json make_sample(double now, const json &entry, bool is_interface, const json &source_record) const;
	void append_entries(double now, const json::array_t &entries, bool is_interface, const json &source_record);
	void update_rollup(const json &sample);
	void observe_sample(const json &sample);
	void flush_bucket();
};

#endif /* METRIC_SAMPLE_PROJECTOR_H */
#ifndef STREAM_STATE_PROJECTOR_H
#define STREAM_STATE_PROJECTOR_H

#include <cstdint>
#include <filesystem>
#include <string>

#include "json.h"
#include "writer.h"

class stream_state_projector {
public:
	struct config {
		std::filesystem::path root_dir;
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
		std::uint32_t inactive_retention_sec{300U};
	};

	explicit stream_state_projector(config cfg);

	bool observe_run(const json &record, double time);
	bool apply_event(const json &event);
	json snapshot(double time) const;
	json export_state() const;
	void import_state(const json &state);
	bool prune_inactive();

private:
	config m_cfg;
	std::unique_ptr<time_rotating_writer> m_delta_writer;
	json m_streams = json::object();
	std::string m_active_run_id;
	double m_active_run_started_at{0.0};
	std::int64_t m_last_checkpoint_minute{-1};
	double m_state_time{0.0};
	unsigned m_cache_sweep_bucket{0};
	json m_restored_state = json::object();

	std::filesystem::path cache_path(const std::string &stream_key, const std::string &flow_key) const;
	json load_inactive(const std::string &stream_key, const std::string &flow_key) const;
	bool store_inactive(const std::string &stream_key, const std::string &flow_key, const json &state) const;
	void restore_inactive(const std::string &stream_key, const std::string &flow_key);
	void sweep_inactive_cache();
	void write_delta(const json &event, const char *action);
	void checkpoint_if_needed(double time);
	void write_checkpoint(double time) const;
};

