export type SchemaMetric = { key: string; description?: string; unit?: string; preview: boolean };
/** Read schema metadata only, without STM settings, policies or detected targets. */
export function parseMetricSchema(value: unknown): { metrics: SchemaMetric[]; protocols: string[] } {
  const root = value as any;
  const properties = root?.$defs?.alertRule?.properties;
  const items = properties?.metric?.oneOf;
  const protocols = properties?.proto?.enum;
  if (!Array.isArray(items) || !Array.isArray(protocols)) throw new Error("invalid alerts schema: metric or protocol definitions are missing");
  const metrics: SchemaMetric[] = [];
  const keys = new Set<string>();
  for (const item of items) {
    if (!item || typeof item !== "object" || typeof item.const !== "string") continue;
    if (keys.has(item.const)) throw new Error("Duplicate schema metric: " + item.const);
    keys.add(item.const);
    metrics.push({ key: item.const, ...(typeof item.description === "string" ? { description: item.description } : {}), ...(typeof item["x-unit"] === "string" ? { unit: item["x-unit"] } : {}), preview: item["x-ui-preview"] === true });
  }
  return { metrics: metrics.sort((a, b) => a.key.localeCompare(b.key)), protocols: protocols.filter((item): item is string => typeof item === "string") };
}
