static void resume_tests(const std::filesystem::path &root) {
    const auto file = root / "resume/20261021/00.ndjson";
    std::filesystem::create_directories(file.parent_path());
    const auto record = [](const char *id) { return json{{"record_id", id}, {"capture_id", "cap"}}.dump(); };
    std::ofstream(file, std::ios::binary) << '\n' << record("cap:0") << "\r\n";
    journal_reader reader(root / "resume");
    journal_reader::cursor cursor;
    const auto read = [&](std::vector<std::string> expected) {
        std::vector<std::string> actual;
        const auto result = reader.read_after(cursor, [&](const json &value) {
            actual.push_back(value.at("record_id").get<std::string>());
            return 0;
        });
        check(actual == expected && result.records == expected.size(), "resumed records differ");
    };
    read({"cap:0"});
    cursor = journal_reader::cursor_from_json(journal_reader::cursor_json(cursor));
    check(cursor.offset == std::filesystem::file_size(file), "byte offset must include leading blank and CRLF");
    const auto saved = cursor.offset;
    std::ofstream(file, std::ios::app | std::ios::binary) << "{\"record_id\":\"cap:1";
    read({});
    check(cursor.offset == saved, "incomplete record must not advance cursor");
    std::ofstream(file, std::ios::app | std::ios::binary) << "\",\"capture_id\":\"cap\"}\n";
    read({"cap:1"});
    const auto before_unterminated = cursor.offset;
    std::ofstream(file, std::ios::app | std::ios::binary) << record("cap:2");
    read({});
    check(cursor.offset == before_unterminated, "JSON without newline must remain pending");
    std::ofstream(file, std::ios::app | std::ios::binary) << '\n';
    read({"cap:2"});
    read({});
    check(cursor.offset == std::filesystem::file_size(file), "append cursor offset");

    std::ofstream(file, std::ios::app | std::ios::binary) << record("cap:3") << '\n';
    const auto before_failure = cursor.offset;
    const auto failed = reader.read_after(cursor, [](const json &) { return -1; });
    check(failed.records == 0 && cursor.offset == before_failure, "failed handler must be retried");
    read({"cap:3"});

    // Replacement can grow the file, so size alone does not identify a new generation.
    auto replacement = json{{"record_id", "cap:new0"}, {"capture_id", "cap"}, {"padding", std::string(2048, 'x')}};
    std::ofstream(file, std::ios::binary) << replacement.dump() << '\n' << record("cap:new1") << '\n';
    read({"cap:new0", "cap:new1"});
    std::ofstream(file, std::ios::binary) << record("cap:new0") << '\n';
    read({"cap:new0"});
    std::ofstream(file, std::ios::binary).close();
    read({});
    check(cursor.offset == 0, "empty replacement must reset cursor");
    std::ofstream(file, std::ios::binary) << record("cap:after-empty") << '\n';
    read({"cap:after-empty"});

    const auto next = file.parent_path() / "00.part1.ndjson";
    std::ofstream(next, std::ios::binary) << record("cap:next-part") << '\n';
    std::filesystem::remove(file);
    read({"cap:next-part"});
    check(cursor.path == "20261021/00.part1.ndjson", "resume after old file removal");

    auto legacy = cursor;
    legacy.file_start_record_id.clear();
    std::ofstream(next, std::ios::binary) << json{{"record_id", "other:0"}, {"capture_id", "other"}, {"padding", std::string(2048, 'x')}}.dump() << '\n';
    cursor = legacy;
    read({"other:0"});
}
int main() {
    char pattern[] = "/tmp/stm-journal-storage-XXXXXX";
    const auto temporary = mkdtemp(pattern);
    if(!temporary) return 1;
    const std::filesystem::path root(temporary);
    const double time = 1792540800; // 2026-10-21 00:00 UTC
    try {
        resume_tests(root);
        for(int pass = 0; pass < 2; ++pass) {
            time_logger output("TEST_JOURNAL_STORAGE", root / "restart", 0, 0);
