        std::string line;
        check(bool(std::getline(input, line)) && json::parse(line)["record_id"] == "0", "restart truncated the old record");
        check(bool(std::getline(input, line)) && json::parse(line)["record_id"] == "1", "restart did not append");
        for(int pass = 0; pass < 12; ++pass) {
            time_logger output("TEST_JOURNAL_PARTS", root / "parts", 1, 0);
            output.dump_at(time, {{"record_id", std::to_string(pass)}, {"time", time}});
        }
        journal_reader reader(root / "parts");
        journal_reader::cursor cursor;
        int sequence = 0;
        reader.read_after(cursor, [&](const json &value) {
            check(value["record_id"] == std::to_string(sequence++), "parts replayed out of numeric order"); return 0;
        });
        check(sequence == 12, "restart lost a part");
        check(reader.read_after(cursor, [](const json &) { throw std::runtime_error("cursor reread history"); return 0; }).records == 0, "cursor did not resume");
        std::filesystem::create_directories(root / "partial/20261021");
        std::ofstream(root / "partial/20261021/00.ndjson") << "{\"unfinished\":";
        {
