            output.dump_at(time, {{"record_id", "after-crash"}, {"time", time}});
            const auto path = root / "partial/20261021/00.part1.ndjson";
            check(std::filesystem::exists(path), "partial final record was not sealed");
            int fd = open(path.c_str(), O_RDONLY);
            check(fd >= 0, "cannot open locked file");
            check(flock(fd, LOCK_EX | LOCK_NB) != 0, "active history is not protected from deletion");
            close(fd);
        }
        journal_reader partial(root / "partial");
        cursor = {};
        check(partial.read_after(cursor, [](const json &value) { check(value["record_id"] == "after-crash", "bad resumed record"); return 0; }).records == 1, "sealed partial record prevented recovery");
        std::filesystem::remove_all(root);
        std::cout << "journal storage tests passed\n";
        return 0;
    } catch(const std::exception &error) {
        std::filesystem::remove_all(root);
        std::cerr << error.what() << '\n';
        return 1;
    }
}

