export function queryMetricsSnapshotAt(time: number, timing?: QueryStageTiming, signal?: AbortSignal): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  const query = () => shareHistoryQuery("metrics-snapshot:" + time, sharedSignal => {
    const load = () => queryMetricsSnapshotAtUncached(time, timing, sharedSignal);
    return timing ? timing.run("metrics-snapshot", sharedSignal, load) : load();
  }, signal);
  return timing ? timing.async("snapshot-query", query) : query();
}

async function queryMetricsSnapshotAtUncached(time: number, timing?: QueryStageTiming, signal?: AbortSignal): Promise<{ interfaces: NormalizedInterfaceInput[]; metrics: NormalizedMetricInput[] } | undefined> {
  signal?.throwIfAborted();
  const stats: RangeReadStats | undefined = timing ? { bytesRead: 0, parsedRecords: 0, indexReuses: 0, indexBuilds: 0 } : undefined;
  try {
    const list = () => listSampleFiles("1s", Math.max(0, time - 3600), time);
    const files = timing ? timing.sync("snapshot-files", list) : list();
    timing?.count("snapshotFiles", files.length);
    timing?.count("snapshotLookupFiles", 0);
    timing?.count("snapshotSkippedFiles", 0);
    timing?.count("snapshotReadFiles", 0);
    timing?.count("snapshotMatchedRecords", 0);
    let latestTime = Number.NEGATIVE_INFINITY;
    const latestFiles = new Set<string>();
    const partitions = sampleHourPartitions(files);
    let canPrune = partitions !== undefined, inspected = 0;
    // Keep a complete hour's parts together: a single snapshot can cross a rotation.
    for (const partition of partitions ?? [{ files, from: Number.NEGATIVE_INFINITY, to: Number.POSITIVE_INFINITY }]) {
      for (const file of partition.files) {
        signal?.throwIfAborted();
        inspected += 1;
        timing?.count("snapshotLookupFiles");
        const candidate = await findLatestNdjsonTimeAtOrBefore(file, time, { signal, timing, stats, reader: "chunks",
          stages: { index: "snapshot-index", read: "snapshot-read", build: "snapshot-index-build", wait: "snapshot-index-wait" },
          onIndex: info => {
            if (!info.ordered || info.from !== undefined && info.from < partition.from
              || info.to !== undefined && info.to >= partition.to) canPrune = false;
          } });
        if (candidate === undefined) continue;
        if (candidate > latestTime) {
          latestTime = candidate;
          latestFiles.clear();
          latestFiles.add(file);
        } else if (candidate === latestTime) latestFiles.add(file);
      }
      // The producer partitions samples by their own UTC time. Older hours cannot
      // improve this result; malformed partitions and observed inversions retain a full search.
      if (canPrune && latestTime >= partition.from) {
        timing?.count("snapshotSkippedFiles", files.length - inspected);
        break;
      }
    }
    if (!Number.isFinite(latestTime)) return undefined;
    const interfaces = new Map<string, NormalizedInterfaceInput>();
    const metrics = new Map<string, NormalizedMetricInput>();
    // Preserve the original hour/part order for equal-time overwrites, even after fallback.
    for (const file of files.filter(file => latestFiles.has(file))) {
      signal?.throwIfAborted();
      timing?.count("snapshotReadFiles");
      await readSampleAtTime(file, latestTime, (sample) => {
        if (sample.interface || sample.metric) timing?.count("snapshotMatchedRecords");
        if (sample.interface) interfaces.set(sample.targetKey, sample.interface);
        if (sample.metric) metrics.set(sample.targetKey, sample.metric);
      }, timing, signal, stats);
    }
    signal?.throwIfAborted();
    const materialize = () => ({ interfaces: [...interfaces.values()], metrics: [...metrics.values()] });
    return timing ? timing.sync("snapshot-materialize", materialize) : materialize();
  } finally {
    if (timing && stats) {
      timing.count("snapshotReadBytes", stats.bytesRead);
      timing.count("snapshotParsedRecords", stats.parsedRecords);
      timing.count("snapshotIndexReuses", stats.indexReuses);
      timing.count("snapshotIndexBuilds", stats.indexBuilds);
      timing.count("snapshotIndexReadBytes", stats.indexReadBytes ?? 0);
      timing.count("snapshotIndexEntries", stats.indexEntries ?? 0);
    }
  }
}

