void snapshot_tests(const std::filesystem::path &root) {
	stream_state_projector projector({.root_dir = root, .part_size_bytes = 1024 * 1024, .retention_hours = 1});
	const json scope{{"interface_id", 1}, {"interface_name", "eno1"}, {"vlan", {{"ids", {100}}}}};
	const json alerts{{"jitter", {{"active", true}}}};
	const json recent_alerts = json::array({{{"type", "alert_recovered"}, {"time", 120.0}}});
	const json flow_base{
		{"interface_id", 1}, {"scope", scope}, {"vlan", {{"ids", {100}}}},
		{"endpoint", {{"src", "192.0.2.1:5000"}, {"dst", "239.1.1.1:5000"}}},
		{"role", "media"}, {"first_seen", 100.0}, {"last_seen", 125.0},
		{"alerts", alerts}, {"recent_alerts", recent_alerts},
	};
	json flows = json::object();
	json::array_t expected_flows;
	for(const auto *key : {"flow-a", "flow-z"}) {
		json flow = flow_base;
		flow["flow_key"] = key;
		expected_flows.push_back(flow);
		flow["active"] = true;
		flow["run_id"] = "run-a";
		flows[key] = std::move(flow);
	}
	for(int i = 0; i < 1000; ++i) {
		flows["inactive-" + std::to_string(i)] = {{"active", false}, {"endpoint", flow_base["endpoint"]}};
	}
	flows["missing-active"] = json::object();
	flows["not-boolean-active"] = {{"active", 1}};
	json expected_stream{
		{"stream_key", "stream-a"}, {"name", "RTP test"}, {"interface_id", 1},
		{"scope", scope}, {"vlan", {{"ids", {100}}}},
		{"endpoint", {{"dst", "239.1.1.1:5000"}}}, {"stream_group", "test"},
		{"first_seen", 100.0}, {"last_seen", 125.0},
		{"alerts", alerts}, {"recent_alerts", recent_alerts}, {"flows", expected_flows},
	};
	json stream = expected_stream;
	stream["active"] = true;
	stream["proto"] = "RTP";
	stream["flows"] = std::move(flows);
	stream["run_id"] = "run-a";
	json state{{"streams", {
		{"stream-a", std::move(stream)},
		{"stream-b", {{"stream_key", "stream-b"}, {"active", true}}},
		{"stream-c", {{"stream_key", "stream-c"}, {"active", true}, {"flows", nullptr}}},
		{"stream-d", {{"stream_key", "stream-d"}, {"active", true}, {"flows", json::array()}}},
		{"inactive", {{"active", false}}},
		{"not-boolean-active", {{"active", 1}}},
	}}};
	projector.import_state(state);
	const auto before = projector.export_state();
	json::array_t expected_entries{{{"proto", "RTP"}, {"stream", expected_stream}}};
	for(const auto *key : {"stream-b", "stream-c", "stream-d"}) {
		expected_entries.push_back({{"proto", ""}, {"stream", {{"stream_key", key}, {"flows", json::array()}}}});
	}
	const json expected{{"time", 130.0}, {"streams", std::move(expected_entries)}};
	auto snapshot = projector.snapshot(130.0);
	check(snapshot == expected, "snapshot fields, ordering or active filtering changed");
	check(projector.export_state() == before, "snapshot modified retained state");
	snapshot["streams"][0]["stream"]["flows"][0]["endpoint"]["src"] = "changed";
	check(projector.export_state() == before, "snapshot does not own its data");
	stream_state_projector restored({.root_dir = root / "restored", .part_size_bytes = 1024 * 1024, .retention_hours = 1});
	restored.import_state(before);
	check(restored.snapshot(130.0) == expected, "restored snapshot differs");
}

